          { partName: "Ignition Wire Set", category: "Ignition", oem: { brand: "BMW Genuine", code: "12121705607", approxPrice: "350 EUR" }, crossRef: { brand: "Bremi", code: "236", approxPrice: "140 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=12121705607", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=12121705607" }, note: "Replaces arcing, hard original cables." }
