            { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter Replacement", details: "Replace the large metal inline fuel filter to protect the aging Bosch injectors from rust in the classic metal fuel tank.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" },
            { interval: "Every Service", timeLimit: "1 year", task: "HVAC Blower Motor Check", details: "The E24 lacks a modern cabin filter; inspect and vacuum debris from the HVAC blower motor area under the cowl.", parts: ["Cleaning"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" }
