            { interval: "Immediately (If Leaking)", timeLimit: "Unlimited", task: "Coolant Transfer Pipe Repair", details: "CRITICAL: If coolant weeps from the front hole near the water pump, cut the internal pipe and install an aftermarket expanding stent to save thousands in engine-out labor.", parts: ["Expanding Pipe Kit", "Intake Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "1200 EUR" },
            { interval: "Immediately (If Leaking)", timeLimit: "Unlimited", task: "Alternator Bracket Seal Replacement", details: "CRITICAL: If massive oil leaks occur on the lower driver's side, support the engine, drop the subframe, and replace the 5 EUR gasket to prevent engine starvation.", parts: ["Bracket Gasket", "Labor"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1000+ EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover & Upper Timing Cover Gaskets", details: "CRITICAL: Remove the complex Valvetronic motors, replace the massive rubber gaskets, and reseal the upper timing covers to stop oil leaking onto the hot exhaust manifolds.", parts: ["VCG Sets", "Timing Cover Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "450 EUR" },
            { interval: "60,000 km", timeLimit: "5 years", task: "Spark Plug Replacement", details: "Replace the spark plugs to ensure smooth operation of the massive V8.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "VANOS Solenoid Cleaning/Replacement", details: "Remove and clean the fine mesh screens on the four VANOS solenoids to cure hesitation and rough idle.", parts: ["O-Rings", "Brake Cleaner"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Vacuum Pump Rebuild", details: "Remove the mechanical vacuum pump from the passenger cylinder head and replace the internal/external O-rings to cure severe oil leaks.", parts: ["O-Ring Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Guide Replacement", details: "CRITICAL: If loud rattling is heard on cold start, the incredibly brittle plastic timing guides must be replaced before they shatter and the chain jumps a tooth, destroying the engine.", parts: ["Timing Guide Kit", "Special Tools"], importance: "High", laborDifficulty: "Expert", estimatedCost: "2500+ EUR" }
