            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belts & Tensioners", details: "Replace the main accessory drive belt, the A/C belt, and tensioner pulleys.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine & Transmission Mounts", details: "Replace the sagging rubber mounts to prevent the heavy V8 from shifting and vibrating.", parts: ["Lemförder Mounts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "100,000 km", timeLimit: "10 years", task: "Driveshaft Flex Disc (Guibo)", details: "Inspect and replace the rubber flex disc connecting the transmission to the driveshaft to cure driveline thumping.", parts: ["Febi Flex Disc"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }
