            { interval: "40,000 km", timeLimit: "3 years", task: "Engine Coolant Flush (Primary)", details: "Drain and refill the massive 15L primary cooling system. Vital for preserving the aluminum V8 block.", parts: ["15.0L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" },
            { interval: "40,000 km", timeLimit: "3 years", task: "Charge-Air Coolant Flush", details: "Drain and refill the separate low-temperature cooling circuit for the massive intercoolers.", parts: ["4.5L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
            { interval: "60,000 km", timeLimit: "5 years", task: "Power Steering Fluid Flush", details: "Drain and refill the specific CHF 11S fluid in the steering system.", parts: ["1.2L CHF 11S"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
