          { partName: "Engine Oil Filter", category: "Maintenance", oem: { brand: "BMW Genuine", code: "11427840594", approxPrice: "25 EUR" }, crossRef: { brand: "Mann-Filter", code: "HU 926/5 z", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=HU+926%2F5+z", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=HU+926%2F5+z" }, note: "Cartridge filter." }
