        engineeringData: { blockDesign: "Aluminum block with cast-iron cylinder liners. The B47TU1 is a massive modular overhaul, heavily refined for NVH and efficiency. The timing chain remains at the rear, utilizing incredibly robust guides, completely curing the N47's snapping issues.", crankshaft: "Forged Steel, supported by 5 main bearings. Features balance shafts to counter 4-cylinder vibrations, making it incredibly smooth.", pistonSpeed: "15.0 m/s @ 4000 RPM.", alternator: "150A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with high-flow gallery cooling.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "16-valve DOHC design. The aluminum casting is excellent, but the intake tracts clog incredibly rapidly with EGR carbon.", valveSizes: "Intake: 25.9 mm / Exhaust: 25.9 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Extreme EGR System. The engine uses a highly complex Exhaust Gas Recirculation system to meet Euro 6d-TEMP emissions, which tragically leaks coolant internally, leading to massive engine fires." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Rotor-type pump driven by a dedicated chain.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch CP4 Common Rail High-Pressure Pump. Known for catastrophic internal failure.", maxPressure: "2000 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm", maxSafePowerStock: "250 hp (The turbocharger is the limiting factor).", maxSafeRPM: "4500 RPM", weakestLink: "EGR Cooler (Fire Risk), Turbocharger (Overworked), Bosch CP4 Pump (Fatal), DPF (Clogging), Intake Carbon Buildup." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE (Heavily encrypted - Requires FEMTO unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic failure of the B47 engine.", parts: [ { category: "EGR Cooler (Updated)", brand: "BorgWarner", note: "CRITICAL: The factory cooler leaks coolant and causes engine fires." }, { category: "CP4 Pump Protection Screen", brand: "Whitbread", note: "CRITICAL: Catches shrapnel if the high-pressure fuel pump fails." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber pulley. ONLY use Corteco." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when removing manifold for walnut blasting." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Replace proactively to ensure DPF regeneration." }, { category: "Timing Chain Kit (Complete)", brand: "Genuine BMW / Febi", note: "CRITICAL: Rarely needed early, but extreme high mileage may require it." }, { category: "Engine Mounts", brand: "Lemförder", note: "Vacuum-actuated fluid mounts; replace to cure cabin vibrations." }, { category: "Water Pump", brand: "Pierburg / Saleri", note: "Replace proactively to ensure bulletproof cooling." } ] },
