            { interval: "40,000 km", timeLimit: "3 years", task: "Primary Coolant Flush", details: "Drain and refill the main engine cooling system to prevent internal block corrosion and protect the water pump.", parts: ["8.5L LC-87 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
            { interval: "Every Service", timeLimit: "1 year", task: "AdBlue (SCR) Top-Up", details: "Fill the DEF tank to ensure the emissions system functions and prevents a no-start condition.", parts: ["AdBlue Fluid"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "20 EUR" }
